"use client";

import * as React from "react";
import { useEffect, useState, useCallback } from "react";
import { ActivityCalendar } from "react-activity-calendar";
import {
  ExternalLink,
  AlertCircle,
  GitCommit,
  GitPullRequest,
  GitBranch,
  MessageSquare,
  User,
  Clock,
  Hash,
} from "lucide-react";
import Link from "next/link";
import { useTheme } from "next-themes";
import { format, parseISO, subDays } from "date-fns";

import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
} from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Separator } from "@/components/ui/separator";
import { ScrollArea } from "@/components/ui/scroll-area";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";

interface Commit {
  hash: string;
  repo: string;
  repoOwner: string;
  timestamp: string;
  type: "commit" | "pr" | "issue" | "review";
  count: number; // Number of commits to this repo on this day
}

interface DayData {
  date: string;
  count: number;
  level: number;
  commits: Commit[];
}

interface GithubHeatMapProps {
  username: string;
}

const CONTRIBUTIONS_QUERY = `
  query($username: String!, $from: DateTime!, $to: DateTime!) {
    user(login: $username) {
      contributionsCollection(from: $from, to: $to) {
        contributionCalendar {
          weeks {
            contributionDays {
              date
              contributionCount
              contributionLevel
            }
          }
        }
        commitContributionsByRepository(maxRepositories: 100) {
          repository {
            name
            owner {
              login
            }
          }
          contributions(first: 100) {
            nodes {
              occurredAt
              url
            }
          }
        }
        pullRequestContributions(first: 100) {
          nodes {
            occurredAt
            pullRequest {
              number
              title
              url
              repository {
                name
                owner {
                  login
                }
              }
            }
          }
        }
        issueContributions(first: 100) {
          nodes {
            occurredAt
            issue {
              number
              title
              url
              repository {
                name
                owner {
                  login
                }
              }
            }
          }
        }
      }
    }
  }
`;

export function GithubHeatMap({ username }: GithubHeatMapProps) {
  const { theme, systemTheme } = useTheme();
  const [data, setData] = useState<DayData[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [total, setTotal] = useState(0);
  const [selectedDate, setSelectedDate] = useState<DayData | null>(null);
  const [dialogOpen, setDialogOpen] = useState(false);

  const currentTheme = theme === "system" ? systemTheme : theme;

  const colorTheme = {
    light: ["#ebedf0", "#d1fae5", "#6ee7b7", "#10b981", "#047857"],
    dark: ["#1f2937", "#064e3b", "#047857", "#10b981", "#34d399"],
  };

  const fetchGitHubData = async (user: string) => {
    const token = process.env.NEXT_PUBLIC_GITHUB_TOKEN;

    if (!token) {
      throw new Error("GitHub token not configured");
    }

    const to = new Date().toISOString();
    const from = subDays(new Date(), 365).toISOString();

    const response = await fetch('https://api.github.com/graphql', {
      method: 'POST',
      headers: {
        'Authorization': `bearer ${token}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        query: CONTRIBUTIONS_QUERY,
        variables: { username: user, from, to }
      })
    });

    if (!response.ok) {
      throw new Error(`GitHub API error: ${response.status}`);
    }

    const result = await response.json();

    if (result.errors) {
      throw new Error(result.errors[0].message);
    }

    return result.data.user.contributionsCollection;
  };

  const processContributions = (collection: any): { dayData: DayData[]; totalCount: number } => {
    // Group by date and repo
    const commitsByDate = new Map<string, Map<string, Commit>>();

    // Process commits - group by date and repo
    collection.commitContributionsByRepository?.forEach((repoContrib: any) => {
      const repoName = repoContrib.repository.name;
      const repoOwner = repoContrib.repository.owner.login;

      repoContrib.contributions?.nodes?.forEach((contrib: any) => {
        const date = contrib.occurredAt.split('T')[0];

        if (!commitsByDate.has(date)) {
          commitsByDate.set(date, new Map());
        }

        const dateRepos = commitsByDate.get(date)!;
        const key = `${repoOwner}/${repoName}`;

        if (dateRepos.has(key)) {
          // Increment count for existing repo
          const existing = dateRepos.get(key)!;
          existing.count += 1;
        } else {
          // Add new repo entry
          dateRepos.set(key, {
            hash: contrib.url?.split('/').pop() || '',
            repo: repoName,
            repoOwner: repoOwner,
            timestamp: contrib.occurredAt,
            type: 'commit',
            count: 1,
          });
        }
      });
    });

    // Process PRs
    collection.pullRequestContributions?.nodes?.forEach((contrib: any) => {
      const date = contrib.occurredAt.split('T')[0];

      if (!commitsByDate.has(date)) {
        commitsByDate.set(date, new Map());
      }

      const dateRepos = commitsByDate.get(date)!;
      const key = `pr-${contrib.pullRequest.number}`;

      dateRepos.set(key, {
        hash: String(contrib.pullRequest.number),
        repo: contrib.pullRequest.repository.name,
        repoOwner: contrib.pullRequest.repository.owner.login,
        timestamp: contrib.occurredAt,
        type: 'pr',
        count: 1,
      });
    });

    // Process Issues
    collection.issueContributions?.nodes?.forEach((contrib: any) => {
      const date = contrib.occurredAt.split('T')[0];

      if (!commitsByDate.has(date)) {
        commitsByDate.set(date, new Map());
      }

      const dateRepos = commitsByDate.get(date)!;
      const key = `issue-${contrib.issue.number}`;

      dateRepos.set(key, {
        hash: String(contrib.issue.number),
        repo: contrib.issue.repository.name,
        repoOwner: contrib.issue.repository.owner.login,
        timestamp: contrib.occurredAt,
        type: 'issue',
        count: 1,
      });
    });

    // Build day data from calendar
    const dayData: DayData[] = [];
    let totalCount = 0;

    collection.contributionCalendar.weeks.forEach((week: any) => {
      week.contributionDays.forEach((day: any) => {
        const dateCommits = Array.from(commitsByDate.get(day.date)?.values() || []);

        // If we have a count but no detailed commits, show generic activity
        if (day.contributionCount > 0 && dateCommits.length === 0) {
          dateCommits.push({
            hash: "activity",
            repo: "Other activity",
            repoOwner: username,
            timestamp: `${day.date}T12:00:00Z`,
            type: "commit",
            count: day.contributionCount,
          });
        }

        dayData.push({
          date: day.date,
          count: day.contributionCount,
          level: getLevel(day.contributionLevel),
          commits: dateCommits,
        });

        totalCount += day.contributionCount;
      });
    });

    return { dayData, totalCount };
  };

  const getLevel = (level: string): number => {
    switch (level) {
      case 'NONE': return 0;
      case 'FIRST_QUARTILE': return 1;
      case 'SECOND_QUARTILE': return 2;
      case 'THIRD_QUARTILE': return 3;
      case 'FOURTH_QUARTILE': return 4;
      default: return 0;
    }
  };

  const fetchData = useCallback(async () => {
    if (!username) return;

    try {
      setIsLoading(true);
      setError(null);

      const collection = await fetchGitHubData(username);
      const { dayData, totalCount } = processContributions(collection);

      setData(dayData);
      setTotal(totalCount);
    } catch (err: any) {
      console.error(err);
      setError(err.message);
    } finally {
      setIsLoading(false);
    }
  }, [username]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const handleCellClick = (day: DayData) => {
    setSelectedDate(day);
    setDialogOpen(true);
  };

  const getActivityIcon = (type: Commit["type"]) => {
    switch (type) {
      case "pr":
        return <GitPullRequest className="w-4 h-4 text-blue-500" />;
      case "issue":
        return <MessageSquare className="w-4 h-4 text-amber-500" />;
      case "review":
        return <User className="w-4 h-4 text-purple-500" />;
      default:
        return <GitCommit className="w-4 h-4 text-emerald-500" />;
    }
  };

  const renderBlock = (block: React.ReactElement, activity: DayData) => {
    const trigger = React.cloneElement(block, {
      className:
        "cursor-pointer hover:opacity-80 transition-all duration-200 hover:ring-2 hover:ring-emerald-500/50 hover:ring-offset-1 dark:hover:ring-offset-zinc-950",
      onClick: () => handleCellClick(activity),
    });

    return (
      <Tooltip key={activity.date}>
        <TooltipTrigger asChild>{trigger}</TooltipTrigger>
        <TooltipContent
          side="top"
          className="hidden sm:block bg-zinc-900 text-white dark:bg-slate-50 dark:text-zinc-900 px-3 py-2 border-none shadow-lg"
        >
          <p className="font-semibold text-sm mb-1">
            {format(parseISO(activity.date), "MMMM d, yyyy")}
          </p>
          <p className="text-xs text-zinc-300 dark:text-slate-600">
            {activity.count}{" "}
            {activity.count === 1 ? "contribution" : "contributions"}
          </p>
        </TooltipContent>
      </Tooltip>
    );
  };

  const GraphSkeleton = () => (
    <div className="flex gap-1 py-0.5 min-h-3xl">
      {Array.from({ length: 53 }).map((_, i) => (
        <div key={i} className="flex flex-col gap-1">
          {Array.from({ length: 10 }).map((_, j) => (
            <Skeleton key={j} className="w-3 h-3 rounded-[2px]" />
          ))}
        </div>
      ))}
    </div>
  );

  if (error) {
    return (
      <Alert variant="destructive" className="border-red-200 dark:border-red-900">
        <AlertCircle className="h-4 w-4" />
        <AlertDescription>
          Failed to load GitHub data: {error}
        </AlertDescription>
      </Alert>
    );
  }

  return (
    <TooltipProvider delayDuration={100}>
      <Card className="overflow-hidden min-h-3xl border-slate-100 dark:border-zinc-800">
        <CardHeader className="pb-3">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <Avatar className="h-8 w-8">
                <AvatarImage
                  src={`https://github.com/${username}.png`}
                  alt={username}
                />
                <AvatarFallback className="bg-emerald-100 text-emerald-700 text-xs">
                  {username.slice(0, 2).toUpperCase()}
                </AvatarFallback>
              </Avatar>
              <div>
                <CardTitle className="text-lg">GitHub Contributions</CardTitle>
                {isLoading ? (
                  <CardDescription>
                    <Skeleton className="w-24 h-4 mt-1" />
                  </CardDescription>
                ) : (
                  <CardDescription>
                    <span className="font-medium text-emerald-600 dark:text-emerald-400">
                      {total.toLocaleString()}
                    </span>{" "}
                    contributions last year
                  </CardDescription>
                )}
              </div>
            </div>

            <Button
              size="icon"
              variant="ghost"
              asChild
              className="hover:text-emerald-600 hover:bg-emerald-50 dark:hover:bg-emerald-900/20"
            >
              <Link
                href={`https://github.com/${username}`}
                target="_blank"
                rel="noopener noreferrer"
              >
                <ExternalLink className="h-4 w-4" />
              </Link>
            </Button>
          </div>
        </CardHeader>

        <CardContent className="p-4 sm:p-6">
          {isLoading ? (
            <div className="overflow-x-auto pb-4">
              <div className="min-w-[750px]">
                <GraphSkeleton />
              </div>
            </div>
          ) : (
            <div className="overflow-x-auto pb-4 scrollbar-hide -mx-4 px-4 sm:mx-0 sm:px-0">
              <div className="min-w-[750px]">
                <ActivityCalendar
                  data={data}
                  theme={colorTheme}
                  colorScheme={currentTheme === "dark" ? "dark" : "light"}
                  blockSize={12}
                  blockMargin={4}
                  blockRadius={3}
                  hideTotalCount
                  renderBlock={renderBlock}
                />
              </div>
            </div>
          )}
        </CardContent>
      </Card>

      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent className="sm:max-w-lg max-h-[80vh] p-0 gap-0">
          <DialogHeader className="p-6 pb-2">
            <div className="flex items-center justify-between">
              <div>
                <DialogTitle className="text-xl font-semibold">
                  {selectedDate &&
                    format(parseISO(selectedDate.date), "MMMM d, yyyy")}
                </DialogTitle>
                <DialogDescription className="mt-1">
                  <span className="text-2xl font-bold text-emerald-600 dark:text-emerald-400">
                    {selectedDate?.count || 0}
                  </span>
                  <span className="text-muted-foreground ml-1">
                    contributions
                  </span>
                </DialogDescription>
              </div>
            </div>
          </DialogHeader>

          <Separator />

          <ScrollArea className="max-h-[400px]">
            <div className="p-6 space-y-4">
              {selectedDate?.commits && selectedDate.commits.length > 0 ? (
                selectedDate.commits.map((commit, idx) => (
                  <div
                    key={idx}
                    className="flex items-start gap-3 p-3 rounded-lg bg-slate-50 dark:bg-zinc-900/50 border border-slate-100 dark:border-zinc-800 hover:border-emerald-200 dark:hover:border-emerald-800 transition-colors"
                  >
                    <div className="mt-0.5">{getActivityIcon(commit.type)}</div>

                    <div className="flex-1 min-w-0 space-y-1">
                      <div className="flex items-center gap-2 flex-wrap">
                        <p className="text-sm font-medium">
                          {commit.repo}
                        </p>
                        {commit.count > 1 && (
                          <Badge
                            variant="secondary"
                            className="text-xs bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400"
                          >
                            {commit.count} commits
                          </Badge>
                        )}
                        {commit.type === "pr" && (
                          <Badge
                            variant="secondary"
                            className="text-xs bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400"
                          >
                            PR #{commit.hash}
                          </Badge>
                        )}
                        {commit.type === "issue" && (
                          <Badge
                            variant="secondary"
                            className="text-xs bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400"
                          >
                            Issue #{commit.hash}
                          </Badge>
                        )}
                      </div>

                      <div className="flex items-center gap-3 text-xs text-muted-foreground flex-wrap">
                        <span className="flex items-center gap-1 font-mono">
                          <Hash className="w-3 h-3" />
                          {commit.hash.substring(0, 7)}
                        </span>
                        <span className="flex items-center gap-1">
                          <Clock className="w-3 h-3" />
                          {format(parseISO(commit.timestamp), "HH:mm")}
                        </span>
                      </div>
                    </div>

                    {/* Link to repo */}
                    <Button
                      variant="ghost"
                      size="icon"
                      className="h-8 w-8 shrink-0"
                      asChild
                    >
                      <Link
                        href={`https://github.com/${commit.repoOwner}/${commit.repo}`}
                        target="_blank"
                        rel="noopener noreferrer"
                        title={`View ${commit.repoOwner}/${commit.repo}`}
                      >
                        <ExternalLink className="h-4 w-4 text-muted-foreground" />
                      </Link>
                    </Button>
                  </div>
                ))
              ) : (
                <div className="text-center py-8 text-muted-foreground">
                  <GitCommit className="w-12 h-12 mx-auto mb-3 opacity-20" />
                  <p>No contributions on this day</p>
                </div>
              )}
            </div>
          </ScrollArea>

          <Separator />

          <div className="p-4 bg-slate-50 dark:bg-zinc-900/50 flex justify-between items-center">
            <div className="flex gap-2">
              <Badge variant="outline" className="text-xs">
                <GitCommit className="w-3 h-3 mr-1" />
                Commits
              </Badge>
              <Badge variant="outline" className="text-xs">
                <GitPullRequest className="w-3 h-3 mr-1" />
                PRs
              </Badge>
            </div>
            <Button variant="outline" size="sm" className="gap-2" asChild>
              <Link
                href={`https://github.com/${username}`}
                target="_blank"
                rel="noopener noreferrer"
              >
                View Profile
                <ExternalLink className="w-3 h-3" />
              </Link>
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </TooltipProvider>
  );
}

"use client";

import * as React from "react";
import { motion, SVGMotionProps } from "framer-motion";
import { cn } from "@/lib/utils";

interface TextWritingEffectProps extends SVGMotionProps<SVGSVGElement> {
  text: string;
  fontClassName?: string;
  speed?: number;
  color?: string;
  strokeWidth?: number;
}

export function TextWritingEffect({
  text,
  fontClassName,
  speed = 2,
  color = "currentColor",
  strokeWidth = 1.5,
  className,
  ...props
}: TextWritingEffectProps) {
  const pathLength = 1000;

  return (
    <div
      className={cn(
        "flex items-center justify-center overflow-hidden w-full h-auto",
        className
      )}
    >
      <motion.svg
        key={`${text}-${fontClassName}`}
        xmlns="http://www.w3.org/2000/svg"
        viewBox="0 0 800 200"
        className="w-full h-full overflow-visible"
        {...props}
      >
        <defs>
          <linearGradient id="textGradient" x1="0%" y1="0%" x2="100%" y2="0%">
            <stop offset="0%" stopColor={color} stopOpacity="1" />
            <stop offset="100%" stopColor={color} stopOpacity="0.8" />
          </linearGradient>
        </defs>

        {/* Outline / Stroke Animation */}
        <motion.text
          x="50%"
          y="50%"
          textAnchor="middle"
          dominantBaseline="middle"
          className={cn("text-7xl fill-transparent", fontClassName)}
          style={{ stroke: color }}
          strokeWidth={strokeWidth}
          strokeLinecap="round"
          initial={{
            strokeDasharray: pathLength,
            strokeDashoffset: pathLength,
          }}
          animate={{
            strokeDashoffset: 0,
          }}
          transition={{
            duration: speed,
            ease: "easeInOut",
          }}
        >
          {text}
        </motion.text>

        {/* Fill Animation */}
        <motion.text
          x="50%"
          y="50%"
          textAnchor="middle"
          dominantBaseline="middle"
          className={cn("text-7xl stroke-transparent", fontClassName)}
          style={{ fill: color }}
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{
            duration: 1,
            ease: "easeOut",
            delay: speed * 0.6,
          }}
        >
          {text}
        </motion.text>
      </motion.svg>
    </div>
  );
}

import { Button } from "@/components/ui/button";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";

// Define the shape of the props
interface GitHubStarsProps {
  repo: string;
}

// Define the shape of the GitHub API response (partial)
interface GitHubRepoData {
  stargazers_count: number;
}

// 1. Helper function to fetch real data from GitHub API
async function getStarCount(repo: string): Promise<number> {
  try {
    const res = await fetch(`https://api.github.com/repos/${repo}`, {
      next: { revalidate: 3600 },
    });

    if (!res.ok) return 0;

    const data = (await res.json()) as GitHubRepoData;
    return data.stargazers_count || 0;
  } catch (error) {
    console.error("Failed to fetch stars:", error);
    return 0;
  }
}

// 2. This is now an async Server Component
export async function GitHubStars({
  repo,
}: GitHubStarsProps): Promise<JSX.Element> {
  // Fetch the real count automatically
  const stargazersCount = await getStarCount(repo);

  return (
    <TooltipProvider>
      <Tooltip delayDuration={200}>
        <TooltipTrigger asChild>
          <Button
            className="flex items-center w-fit gap-2 px-3 text-muted-foreground hover:text-primary"
            variant="outline"
            size="sm"
            asChild
          >
            <a
              href={`https://github.com/${repo}`}
              target="_blank"
              rel="noopener noreferrer"
            >
              {/* GitHub Icon */}
              <svg
                viewBox="0 0 24 24"
                className="h-4 w-4 fill-current"
                aria-hidden="true"
              >
                <path d="M12 .297c-6.63 0-12 5.373-12 12 0 5.303 3.438 9.8 8.205 11.385.6.113.82-.258.82-.577 0-.285-.01-1.04-.015-2.04-3.338.724-4.042-1.61-4.042-1.61C4.422 18.07 3.633 17.7 3.633 17.7c-1.087-.744.084-.729.084-.729 1.205.084 1.838 1.236 1.838 1.236 1.07 1.835 2.809 1.305 3.495.998.108-.776.417-1.305.76-1.605-2.665-.3-5.466-1.332-5.466-5.93 0-1.31.465-2.38 1.235-3.22-.135-.303-.54-1.523.105-3.176 0 0 1.005-.322 3.3 1.23.96-.267 1.98-.399 3-.405 1.02.006 2.04.138 3 .405 2.28-1.552 3.285-1.23 3.285-1.23.645 1.653.24 2.873.12 3.176.765.84 1.23 1.91 1.23 3.22 0 4.61-2.805 5.625-5.475 5.92.42.36.81 1.096.81 2.22 0 1.606-.015 2.896-.015 3.286 0 .315.21.69.825.57C20.565 22.092 24 17.592 24 12.297c0-6.627-5.373-12-12-12" />
              </svg>

              <span className="font-semibold">Star</span>

              <span className="h-4 w-[1px] bg-border mx-1" />

              <span className="text-[13px] tabular-nums">
                {new Intl.NumberFormat("en-US", {
                  notation: "compact",
                  compactDisplay: "short",
                })
                  .format(stargazersCount)
                  .toLowerCase()}
              </span>
            </a>
          </Button>
        </TooltipTrigger>
        <TooltipContent className="font-sans">
          {new Intl.NumberFormat("en-US").format(stargazersCount)} stars
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
}
